const payload = $input.first().json.body ?? $input.first().json;

const contactId = payload.contact?.id;
const contactName = payload.contact?.name ?? 'Sem nome';
const sessionId = payload.sessionId ?? payload.session?.id;
const platform = payload.channel?.platform?.toUpperCase();
const utmSource = payload.session?.utm?.source?.toUpperCase() ?? null;
const headline = payload.session?.utm?.headline ?? payload.questions?.headline ?? null;

// utmSource tem prioridade sobre platform
const origem = utmSource ?? platform ?? 'DESCONHECIDO';

// tagId      = ID da tag no painel CRM (Cards)
// contactTagId = ID da etiqueta de contato (Core Helena)
let tagName, tagId, contactTagId;
if (origem.includes('FACEBOOK')) {
  tagName      = 'Facebook';
  tagId        = 'fb7781a8-9e21-4241-a7d7-ee8e82ffbf6c'; // painel
  contactTagId = '0a6eca24-bf61-4dc6-b607-9b35db4e7cfc'; // contato
} else if (origem.includes('INSTAGRAM')) {
  tagName      = 'Instagram';
  tagId        = '9dd2d9ca-41d5-4f67-b445-2dc73efe6b2b'; // painel
  contactTagId = 'ec81194d-5d4a-4d03-b954-2bb9cab71069'; // contato
} else {
  tagName      = 'Orgânico';
  tagId        = '5c74d4d0-8222-4f2f-999b-f60a96bed915'; // painel
  contactTagId = '28a025a3-3cf1-4b17-b91c-016e21b96477'; // contato
}

const stepId  = '8cde1f9f-1c5a-4989-99c2-773c86d364e0'; // Etapa: Leads
const panelId = '3b98f0bf-fea4-47b7-a922-2f3981220722'; // Painel: Agendamentos IA
const position = Date.now();

const agora = new Date();
const dataEntrada = agora.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const horaEntrada = agora.toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });

let descricao = `Entrada: ${dataEntrada} às ${horaEntrada}`;
if (headline) {
  descricao += `\nCampanha: ${headline}`;
}

const cardBody = {
  panelId,
  stepId,
  title: contactName,
  description: descricao,
  contactIds: [contactId],
  tagIds: [tagId]
};
const cardBodyJson = JSON.stringify(cardBody);

return [{ json: { contactId, contactName, sessionId, platform, utmSource, tagName, tagId, contactTagId, stepId, panelId, position, descricao, cardBodyJson } }];
